use unicode_segmentation::{GraphemeCursor,UnicodeSegmentation};
fn category(grapheme: &str) -> u8 {
    if grapheme.chars().all(char::is_whitespace) {
        0
    } else if grapheme
        .chars()
        .any(|character| character.is_alphanumeric() || character == '_')
    {
        1
    } else {
        2
    }
}
fn reference_left(text: &str, at: usize) -> usize {
    let mut result = at;
    let mut kind = None;
    for (offset, grapheme) in text[..at].grapheme_indices(true).rev() {
        let current = category(grapheme);
        if kind.is_some_and(|kind| kind != current) {
            break;
        }
        result = offset;
        if current != 0 {
            kind = Some(current);
        }
    }
    result
}
fn reference_right(text: &str, at: usize) -> usize {
    let mut result = at;
    let mut kind = None;
    for (offset, grapheme) in text[at..].grapheme_indices(true) {
        let current = category(grapheme);
        if kind.is_some_and(|kind| kind != current) && current != 0 {
            break;
        }
        result = at + offset + grapheme.len();
        if current == 0 {
            kind = Some(0);
        } else {
            kind = Some(current);
        }
    }
    result
}
// A run of ASCII whitespace consists entirely of category-zero clusters, except
// where its endpoint joins a neighboring Unicode cluster (e.g. Prepend or Extend).
// Prove that seam before bypassing per-grapheme classification. Newlines and
// CRLF stay part of the same run; the cursor sees the original sliced source.
fn whitespace_end(text: &str, at: usize, left: bool) -> Option<usize> {
    let offset = if left {
        at - text.as_bytes()[..at]
            .iter()
            .rev()
            .take_while(|byte| byte.is_ascii_whitespace())
            .count()
    } else {
        at + text.as_bytes()[at..]
            .iter()
            .take_while(|byte| byte.is_ascii_whitespace())
            .count()
    };
    if offset == at {
        return None;
    }
    let mut seam = GraphemeCursor::new(offset, text.len(), true);
    let end = if seam
        .is_boundary(text, 0)
        .expect("complete source supplies whitespace seam context")
    {
        offset
    } else if left {
        seam.next_boundary(text, 0)
            .expect("complete source supplies whitespace seam context")?
    } else {
        seam.prev_boundary(text, 0)
            .expect("complete source supplies whitespace seam context")?
    };
    // Leave a joined endpoint cluster to ordinary classification, without
    // rescanning the entire run once for each preceding whitespace character.
    ((left && end < at) || (!left && end > at)).then_some(end)
}

fn word_left(text: &str, at: usize) -> usize {
    let text = &text[..at];
    let mut result = at;
    let mut kind = None;
    let mut cursor = GraphemeCursor::new(at, text.len(), true);
    while cursor.cur_cursor() > 0 {
        let end = cursor.cur_cursor();
        if kind.is_none()
            && let Some(offset) = whitespace_end(text, end, true)
        {
            result = offset;
            cursor = GraphemeCursor::new(offset, text.len(), true);
            continue;
        }
        let offset = cursor
            .prev_boundary(text, 0)
            .expect("complete source supplies word cursor context")
            .unwrap_or(0);
        let current = category(&text[offset..end]);
        if kind.is_some_and(|kind| kind != current) {
            break;
        }
        result = offset;
        if current != 0 {
            kind = Some(current);
        }
    }
    result
}
fn word_right(text: &str, at: usize) -> usize {
    let text = &text[at..];
    let mut result = 0;
    let mut kind = None;
    let mut cursor = GraphemeCursor::new(0, text.len(), true);
    while cursor.cur_cursor() < text.len() {
        let offset = cursor.cur_cursor();
        if let Some(end) = whitespace_end(text, offset, false) {
            result = end;
            kind = Some(0);
            cursor = GraphemeCursor::new(end, text.len(), true);
            continue;
        }
        let end = cursor
            .next_boundary(text, 0)
            .expect("complete source supplies word cursor context")
            .unwrap_or(text.len());
        let current = category(&text[offset..end]);
        if kind.is_some_and(|kind| kind != current) && current != 0 {
            break;
        }
        result = end;
        kind = Some(current);
    }
    at + result
}

use std::{hint::black_box,time::Instant};
fn main() {
 let cases = [
  ("rows-lf",format!("word{}next", "                                        \n".repeat(19000))),
  ("rows-crlf",format!("word{}next", "                                        \r\n".repeat(19000))),
  ("joined-seam",format!("\u{0600}{}\u{0301}word", " ".repeat(800000))),
  ("ordinary",String::from("one two three")),
 ];
 for (name, text) in cases {
  for left in [false,true] {
   let at=if left { match name { "rows-lf" | "rows-crlf" => text.len()-4, "joined-seam" => text.find('\u{0301}').unwrap(), _ => text.len() } } else {0};
   let old:fn(&str,usize)->usize=if left {reference_left} else {reference_right};
   let new:fn(&str,usize)->usize=if left {word_left} else {word_right};
   assert_eq!(old(&text,at),new(&text,at));
   for repetition in 0..20 {
    for candidate in if repetition%2==0 {[false,true]}else{[true,false]} {
     let f=if candidate{new}else{old};let before=Instant::now();
     let result=black_box(f(black_box(&text),black_box(at)));
     println!("{{\"case\":\"{}\",\"bytes\":{},\"left\":{},\"candidate\":{},\"repetition\":{},\"result\":{},\"ms\":{}}}",name,text.len(),left,candidate,repetition,result,before.elapsed().as_secs_f64()*1000.0);
    }
   }
  }
 }
}
